referenceFixTemplate:
#include <iostream>
#include <string>
using namespace std;

struct Door {
    string who;
    Door(string w) : who(w) { cout << "推开 " << who << endl; }
    ~Door() { cout << "关上 " << who << endl; }
};

int main() {
    {
        Door d("{who}");
        cout << "在屋里翻了半天鱼干" << endl;
    }
    cout << "收工" << endl;
    return 0;
}
